  isValidElement,
  PropsWithChildren,
  ReactNode,
  ReactElement,
} from 'react';

type WithOptionalClassName = PropsWithChildren<{ className?: string }>;

/**
 * 주어진 ReactElement를 Slot으로 감싸고,
 * 외부에서 주어진 children 중 해당 Slot 요소를 찾아 props를 병합해 렌더링하는 고차 컴포넌트
 */
export const Slot = (children: ReactNode): React.FC<WithOptionalClassName> =>
  function SlotComponent(props: WithOptionalClassName): ReactElement | null {
    if (isValidElement<WithOptionalClassName>(children)) {
      const mergedChildren = Children.map(props.children, child =>
        child === children ? children.props.children : child
      );

      return createElement(children.type, {
        ...children.props,
        ...props,
        children: mergedChildren,
      });
    }

    return null;
  };

import React, { useState } from 'react'

interface LazyPopupProps {
  open: boolean
  lazy?: boolean
  children: React.ReactNode
}

export const LazyPopup = ({ open, lazy = false, children }: LazyPopupProps) => {
  const [loaded, setLoaded] = useState(!lazy)

  const handleCapture = (e: React.SyntheticEvent) => {
    if (!lazy || loaded) return
    if ((e.target as HTMLElement).tagName === 'IMG') {
      setLoaded(true)
    }
  }

  const visible = open && (!lazy || loaded)

  return visible ? (
    <div className="popup" onLoadCapture={handleCapture}>
      {children}
    </div>
  ) : null
}
